effect:non-scaling-stroke;transition:r .12s ease}.hover-guide{stroke:#cbd8e8;stroke-width:1;stroke-dasharray:4 4;vector-effect:non-scaling-stroke}.trend-tooltip{position:absolute;top:24px;transform:translateX(-50%);z-index:3;min-width:118px;padding:9px 10px;border:1px solid #dfe7f1;border-radius:8px;background:rgba(255,255,255,.98);box-shadow:0 8px 24px rgba(38,66,112,.12);pointer-events:none}.trend-tooltip strong{display:block;margin-bottom:5px;color:#17304f;font-size:11px}.trend-tooltip span{display:flex;align-items:center;gap:6px;margin-top:3px;color:#60718a;font-size:11px}.success-point{fill:#22a06b}.failed-point{fill:#ef6258}.x-label{fill:#96a3b4;font-size:9px;text-anchor:middle}.period-label{color:#9aa7b7;font-size:11px}.pie-wrap{display:flex;flex-direction:column;align-items:center;padding-top:8px}.pie-chart{width:174px;height:174px;border-radius:50%;display:grid;place-items:center;box-shadow:inset 0 0 0 1px rgba(255,255,255,.22)}.pie-chart.empty{background:#edf2f7}.pie-empty{display:flex;align-items:center;justify-content:center;width:100%;height:100%;color:#98a4b4;font-size:12px}.pie-legend{width:100%;margin-top:18px}.pie-legend>div{display:grid;grid-template-columns:1fr auto 44px;align-items:center;padding:8px 4px;border-top:1px solid #f0f3f7;color:#6f7f95;font-size:12px}.pie-legend b{color:#344b66;font-size:13px}.pie-legend em{font-style:normal;text-align:right;color:#8b99ad}.task-card{overflow:visible}.task-toolbar{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--ds-border-soft)}.task-types{display:flex;gap:4px}.task-types button{border:0;background:transparent;border-radius:5px;padding:7px 12px;color:#667085;font-size:13px}.task-types button.active{background:#edf3ff;color:#2f6fed;font-weight:600}.task-table .op-col{width:270px}.task-name{font-weight:600;color:#24364b}.task-table small{display:block;margin-top:3px;color:#98a2b3}.task-actions{white-space:nowrap;overflow:visible!important}.task-